package com.booksyde.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="marketplace_sellers",schema="public") public class MarketplaceSellerEntity { @Id @Column(name="user_id") private UUID userId; @Column(nullable=false) private boolean featured; @Column(name="sandbox_charges_enabled",nullable=false) private boolean sandboxChargesEnabled; @Column(name="sandbox_payouts_enabled",nullable=false) private boolean sandboxPayoutsEnabled; @Column(name="sandbox_details_submitted",nullable=false) private boolean sandboxDetailsSubmitted; @Column(name="live_charges_enabled",nullable=false) private boolean liveChargesEnabled; @Column(name="live_payouts_enabled",nullable=false) private boolean livePayoutsEnabled; @Column(name="live_details_submitted",nullable=false) private boolean liveDetailsSubmitted; @Column(name="stripe_sandbox_account_id") private String stripeSandboxAccountId; @Column(name="stripe_live_account_id") private String stripeLiveAccountId; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; protected MarketplaceSellerEntity(){} public UUID getUserId(){return userId;} public boolean isFeatured(){return featured;} public boolean isSandboxReady(){return sandboxChargesEnabled&&sandboxPayoutsEnabled&&sandboxDetailsSubmitted&&stripeSandboxAccountId!=null;} public boolean isLiveReady(){return liveChargesEnabled&&livePayoutsEnabled&&liveDetailsSubmitted&&stripeLiveAccountId!=null;} public String getStripeSandboxAccountId(){return stripeSandboxAccountId;} public String getStripeLiveAccountId(){return stripeLiveAccountId;} public boolean isActive(){return true;} }
